import sys

def main():
    data = sys.stdin.buffer.read().split(b'\n')
    d = {}
    get = d.get
    for line in data[1:]:
        if not line:
            continue
        parts = line.split(b',')
        if len(parts) < 3:
            continue
        c = parts[1]
        d[c] = get(c, 0.0) + float(parts[2])
    out = []
    for c in sorted(d):
        out.append(c.decode() + ',' + '%.2f' % d[c])
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))

main()
